      "content": "{\n  \"name\": \"dsh-restart-dock\",\n  \"version\": \"0.1.5\",\n  \"description\": \"DSH 界面里的一条小坞：点一下就重启宿主，带进度和结果回执。 A small dock inside the DSH Web UI: one click restarts the host and reports what happened.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./client.js\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./icon\": \"./icon.svg\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"client.js\",\n    \"cordis.patch.yml\",\n    \"locale\",\n    \"icon.svg\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"restart\",\n    \"reload\",\n    \"restart-button\",\n    \"control-dock\",\n    \"host-process\",\n    \"plugin-reload\",\n    \"developer-experience\",\n    \"windows\",\n    \"重启\",\n    \"刷新\",\n    \"控制坞\"\n  ],\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"scripts\": {\n    \"test\": \"node test/smoke.mjs\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/7gzgn/dsh-restart-dock.git\"\n  },\n  \"homepage\": \"https://github.com/7gzgn/dsh-restart-dock#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/7gzgn/dsh-restart-dock/issues\"\n  },\n  \"dsh\": {\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.2.1-rc.2\": \"compatible\",\n        \"0.2.1-rc.3\": \"compatible\",\n        \"0.2.2-rc.1\": \"compatible\"\n      },\n      \"dsh\": \">=0.2.0-rc.1 <0.3.0-0\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"immediately\": true,\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-slots\"\n      ]\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.4 <5.0.0\",\n   