      "path": "lib/index.js",
      "content": "/**\n * dsh-restart-dock · 宿主半\n *\n * 一句话：给界面右下角那个小框提供两个动作 —— **重启宿主**、**看上次重启成没成**。\n * （「刷新页面」不需要宿主，client 半自己就能做。）\n *\n * 为什么要在插件里做重启：\n *   改插件、改 client.js、改 profile 配置之后，DSH 要重载才生效。以前只能关窗口再找快捷方式。\n *   这个入口把那条手工链路变成一次点击 —— 但**默认保守**：重启要连点两次确认，\n *   跨源页面一律拒绝（重启会打断一切，不能让人从别的网页 POST 过来）。\n *\n * 能力面（很小，写清楚）：\n *   GET  /dsh-restart-dock/status   只读：宿主 pid / 端口 / 平台 / 上次重启报告\n *   POST /dsh-restart-dock/restart  动作：起一个脱离宿主的 PowerShell helper 去「停 + 拉」\n *\n * 红线：\n *   · 只接受同源请求，并且要求自定义头 `x-dsh-restart-dock: 1`（跨源会先撞 preflight → 我们不答 → 打不进来）；\n *   · 目标进程**显式探测**：从宿主 pid 往上找到 DSH 应用顶层，找不到就拒绝，绝不猜；\n *   · 响应里不带任何凭据，也不回显无关的进程信息。\n */\n\nimport { spawn } from 'node:child_process';\nimport { fileURLToPath } from 'node:url';\nimport { dirname, join } from 'node:path';\nimport { homedir } from 'node:os';\nimport { mkdirSync, readFileSync, writeFileSync, existsSync, statSync } from 'node:fs';\n\nexport const name = 'dsh-restart-dock';\nexport const inject = [];\n\nconst ROUTE_STATUS = '/dsh-restart-dock/status';\nconst ROUTE_RESTART = '/dsh-restart-dock/restart';\nconst ROUTE_BUNDLE = '/dsh-restart-dock/bundle-ready';\nconst HEADER_MARK = 'x-dsh-restart-dock';\n\n/** 状态目录：与其它自建插件同口径（~/.dsh/<pkg>/）。 */\nfunction stateDir() {\n  const home = process.env.DSH_HOME || join(homedir(), '.dsh');\n  return join(home, 'dsh-restart-dock');\n}\n\nfunction readJson(file) {\n  try {\n    if (!existsSync(file)) return undefined;\n    return JSON.parse(readFileSync(file, 'utf8'));\n  } catch {\n    return undefined;\n  }\n}\n\nfunction writeJson(file, value) {\n  try {\n    mkdirSync(dirname(file), { recursive: true });\n    writeFileSync(file, JSON.stringify(value, null, 2), 'utf8');\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n/* ------------------------------------------------------------ 同源判断 */\n\nconst LOOPBACK = new Set(['127.0.0.1', 'localhost', '0.0.0.0', '::1', '[::1]']);\n\n/**\n * 这个请求能不能被当成「同一个界面发来的」？\n *\n * 真正的防线是**自定义头**：跨源网页想带 `x-dsh-restart-dock`，必须先过 CORS preflight，\n * 而本插件不答 preflight → 浏览器根本不会把真请求发出来。\n * 所以这里不再强求 Origin：实测桌面 app 的 `dsh-app://` 页面连 POST 都不带 Origin、\n * 也不带 `Sec-Fetch-Site`，强求它只会把界面自己的按钮全挡成 403。\n *\n * 剩下的两条是加固：\n *   · 浏览器明确标了 `Sec-Fetch-Site: cross-site` → 直接拒；\n *   · 如果请求带了 Origin，就核对一下（同源 / 桌面协议 / 回环同端口）。\n */\nfunction trustCheck(req, serverOrigin) {\n  if (req.headers[HEADER_MARK] !== '1') return { ok: false, reason: 'missing-mark' };\n\n  const site = req.headers['sec-fetch-site'];\n  if (typeof site === 'string' && site === 'cross-site') return { ok: false, reason: 'site:cross-site' };\n\n  const origin = req.headers.origin;\n  const hasOrigin = typeof origin === 'string' && origin !== '';\n  if (!hasOrigin) return { ok: true, reason: 'no-origin' };\n\n  let asked;\n  try {\n    asked = new URL(origin);\n  } catch {\n    return { ok: false, reason: `bad-origin:${origin}` };\n  }\n\n  // DSH 桌面 app 的页面协议。外部网页无法伪造浏览器自己写的 Origin，所以这一条可信。\n  if (asked.protocol === 'dsh-app:') return { ok: true };\n\n  let base;\n  try {\n    base = new URL(serverOrigin);\n  } catch {\n    return { ok: false, reason: 'bad-server-origin' };\n  }\n  if (asked.protocol !== base.protocol) return { ok: false, reason: `proto:${asked.protocol}|${base.protocol}` };\n  if (asked.port !== base.port) return { ok: false, reason: `port:${asked.port}|${base.port}` };\n  if (asked.hostname === base.hostname) return { ok: true };\n  // 监听在 0.0.0.0 / :: 时，页面实际拿的是 127.0.0.1 或 localhost —— 同一台机器、同一个端口就算同源。\n  if (LOOPBACK.has(asked.hostname) && LOOPBACK.has(base.hostname)) return { ok: true };\n  return { ok: false, reason: `host:${asked.hostname}|${base.hostname}` };\n}\n\nfunction isTrusted(req, serverOrigin) {\n  return trustCheck(req, serverOrigin).ok;\n}\n\n\n/* ------------------------------------------------------------ 响应小工具 */\n\nfunction json(res, code, payload) {\n  const body = JSON.stringify(payload);\n  res.statusCode = code;\n  res.setHeader('content-type', 'application/json; charset=utf-8');\n  res.setHeader('cache-control', 'no-store');\n  res.setHeader('x-content-type-options', 'nosniff');\n  res.end(body);\n}\n\nfunction methodOf(req) {\n  return String(req.method || 'GET').toUpperCase();\n}\n\n/* ------------------------------------------------------------ 重启 */\n\nconst PUBLIC = 'public';\n\n/**\n * 起 helper。**必须包一层 `cmd /c start /b`**：\n * 实测（2026-10-18）在 Windows 上「powershell.exe + -File + detached:true」会\n * 「启动 → 立刻 exit 0 → 脚本一行都没执行」，日志和报告都不出来，按钮看起来毫无反应。\n * 去掉 detached 就正常，但那样 helper 活不过宿主被停掉。\n * 折中：让 cmd 去建进程（`start /b` 立即返回），helper 作为独立进程继续跑，\n * 宿主这边 unref 后立刻得到返回。代价是这里拿到的 pid 是 cmd 的，不是 helper 的。\n */\nfunction spawnHelper(info) {\n  const script = fileURLToPath(new URL('./relaunch.ps1', import.meta.url));\n  // cwd 必须真实存在，否则 spawn 会 ENOENT —— 第一次点的时候状态目录往往还没建。\n  try { mkdirSync(info.stateDir, { recursive: true }); } catch { /* 下面写文件时还会再试一次 */ }\n\n  const psArgs = [\n    '-NoProfile',\n    '-NonInteractive',\n    '-ExecutionPolicy', 'Bypass',\n    '-File', script,\n    '-CallerPid', String(info.callerPid),\n    '-StateDir', info.stateDir,\n    '-DelaySeconds', String(info.delaySeconds),\n  ];\n\n  const child = spawn('cmd.exe', ['/c', 'start', '', '/b', 'powershell.exe', ...psArgs], {\n    detached: true,\n    stdio: 'ignore',\n    windowsHide: true,\n    cwd: info.stateDir,\n    env: { ...process.env, DSH_RESTART_DOCK: String(info.id) },\n  });\n  child.unref();\n  return child.pid;\n}\n\nexport function apply(ctx, config = {}) {\n  const cfg = config || {};\n  const delaySeconds = Number.isFinite(cfg.delaySeconds) ? Math.max(1, cfg.delaySeconds) : 2;\n  const dir = stateDir();\n\n  /** 正在排程/等待的那次重启（防连点）。进程重启后自然清空。 */\n  let inFlight = null;\n  let acceptedAt = 0;\n\n  const startedAt = Date.now();\n\n  function statusPayload() {\n    const last = readJson(join(dir, 'last.json'));\n    const pending = readJson(join(dir, 'pending.json'));\n    return {\n      ok: true,\n      dock: {\n        version: PUBLIC,\n        pid: process.pid,\n        platform: process.platform,\n        uptimeSeconds: Math.round((Date.now() - startedAt) / 1000),\n        stateDir: dir,\n      },\n      restart: {\n        supported: process.platform === 'win32',\n        inFlight: inFlight !== null,\n        // 上次 helper 留下的报告（成功/失败/为什么）。新宿主起来后就能读到。\n        last: last ?? null,\n        // 还没执行完的排程（点击后到 helper 动手之间会看到）。\n        pending: pending ?? null,\n      },\n    };\n  }\n\n  async function onStatus(req, res, webServer) {\n    if (methodOf(req) !== 'GET') return json(res, 405, { ok: false, error: 'method-not-allowed' });\n    let serverOrigin = '';\n    try {\n      serverOrigin = webServer.getOrigin();\n    } catch {\n      serverOrigin = '';\n    }\n    const trust = trustCheck(req, serverOrigin);\n    if (!serverOrigin || !trust.ok) {\n      return json(res, 403, {\n        ok: false,\n        error: 'forbidden',\n        reason: serverOrigin ? trust.reason : 'no-server-origin',\n      });\n    }\n    return json(res, 200, statusPayload());\n  }\n\n  async function onRestart(req, res, webServer) {\n    if (methodOf(req) !== 'POST') return json(res, 405, { ok: false, error: 'method-not-allowed' });\n\n    let serverOrigin = '';\n    try {\n      serverOrigin = webServer.getOrigin();\n    } catch {\n      serverOrigin = '';\n    }\n    const trust = trustCheck(req, serverOrigin);\n    if (!serverOrigin || !trust.ok) {\n      return json(res, 403, {\n        ok: false,\n        error: 'forbidden',\n        reason: serverOrigin ? trust.reason : 'no-server-origin',\n      });\n    }\n\n    if (process.platform !== 'win32') {\n      return json(res, 501, {\n        ok: false,\n        error: 'unsupported-platform',\n        detail: '这个版本只实现了 Windows 的重启；刷新页面在任何平台都能用。',\n      });\n    }\n\n    // 防连点，但**必须会过期**：helper 可能启动失败、或卡在杀进程那一步没真正重启，\n    // 那样宿主还活着，这个标记就会永远卡着，之后点「重启」一律 409，看起来像按钮坏了。\n    // 整个重启最长可能走「延迟 + 等停 20s + 补刀 8s + 拉起 40s」≈ 70 秒，\n    // 所以过期时间给到「延迟 + 120 秒」，别在流程还没走完时把锁放掉。\n    const STALE_MS = (delaySeconds + 120) * 1000;\n    if (inFlight && Date.now() - inFlight.startedAtMs < STALE_MS) {\n      return json(res, 409, {\n        ok: false,\n        error: 'already-scheduled',\n        detail: '已经有一次重启在路上了，别连点。',\n        inFlight: { id: inFlight.id, helperPid: inFlight.helperPid, delaySeconds: inFlight.delaySeconds },\n      });\n    }\n    inFlight = null;\n\n    const id = `rd-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;\n    const record = {\n      id,\n      at: new Date().toISOString(),\n      callerPid: process.pid,\n      hostPid: process.pid,\n      delaySeconds,\n      requestedBy: String(req.headers.origin || ''),\n    };\n\n    writeJson(join(dir, 'pending.json'), record);\n\n    let helperPid;\n    try {\n      helperPid = spawnHelper({ id, callerPid: process.pid, stateDir: dir, delaySeconds });\n    } catch (error) {\n      writeJson(join(dir, 'last.json'), {\n        ok: false,\n        at: new Date().toISOString(),\n        id,\n        error: 'spawn-failed',\n        detail: String(error && error.message ? error.message : error),\n      });\n      return json(res, 500, { ok: false, error: 'spawn-failed', detail: String(error && error.message ? error.message : error) });\n    }\n\n    acceptedAt = Date.now();\n    inFlight = { id, helperPid, at: record.at, delaySeconds, startedAtMs: acceptedAt };\n    writeJson(join(dir, 'pending.json'), { ...record, helperPid });\n\n    return json(res, 202, {\n      ok: true,\n      id,\n      helperPid,\n      delaySeconds,\n      detail: '已排程：约 1~2 秒后宿主会停下并重新拉起，界面会断开几秒。',\n    });\n  }\n\n  /**\n   * 插件包健康检查：告诉界面「现在刷新安不安全」。\n   *\n   * 判据：clientModules 记录的基线（打包前读到的那一代文件的 mtime/ctime/size）\n   * 和磁盘上的实际文件比 —— 不一致，说明文件改了但还没重新打包。\n   * 这个窗口里刷新会拿到坏包（import failed → 整个 web boot 起不来），\n   * 2026-10-18 21:37 就是这么把应用刷崩、只能手动重启的。\n   */\n  async function onBundleReady(req, res, webServer, getClientModules) {\n    if (methodOf(req) !== 'GET') return json(res, 405, { ok: false, error: 'method-not-allowed' });\n\n    let serverOrigin = '';\n    try {\n      serverOrigin = webServer.getOrigin();\n    } catch {\n      serverOrigin = '';\n    }\n    const trust = trustCheck(req, serverOrigin);\n    if (!serverOrigin || !trust.ok) {\n      return json(res, 403, {\n        ok: false,\n        error: 'forbidden',\n        reason: serverOrigin ? trust.reason : 'no-server-origin',\n      });\n    }\n\n    const cm = getClientModules();\n    if (!cm || typeof cm.artifactBaseline !== 'function') {\n      // 拿不到 clientModules 就保守放行 —— 这个接口只做提示，不阻断用户。\n      return json(res, 200, { ok: true, ready: true, detail: 'no-client-modules' });\n    }\n\n    let ready = true;\n    let detail = 'stable';\n    let syntax = 'skipped';\n    try {\n      const base = cm.artifactBaseline(name);\n      if (!base || !base.path) {\n        detail = 'no-baseline';\n      } else {\n        const st = statSync(base.path);\n        const changed = st.mtimeMs !== base.mtimeMs || st.ctimeMs !== base.ctimeMs || st.size !== base.size;\n        ready = !changed;\n        detail = changed ? 'rebuilding' : 'stable';\n      }\n    } catch (error) {\n      detail = 'stat-failed';\n    }\n\n    // 第二道：光看时间戳不够 —— HMR 可能「重建已完成、但产出的包本身是坏的」，\n    // 这种包时间戳正常却一加载就 import failed（2026-10-18 21:41 实测，保护没拦住）。\n    // 所以把当前 bundle 取出来，用 new Function 干跑一遍语法检查；编译不过就不让刷。\n    try {\n      if (typeof cm.graph === 'function' && typeof cm.fetchBundle === 'function') {\n        const graph = cm.graph();\n        const entry = graph && graph.entries ? graph.entries.find((e) => e.id === name) : null;\n        if (entry && entry.rev) {\n          const url = `http://dsh-restart-dock.local/plugins/??${encodeURIComponent(name)}/client.js&rev=${entry.rev}`;\n          const bundleRes = await cm.fetchBundle(new Request(url));\n          if (!bundleRes || !bundleRes.ok) {\n            // **取不到包 = 这孩子不能放行**。之前这里只记 syntax、忘了把 ready 置否，\n            // 结果「包还没准备好」时守卫反而放行，刷新照样 import failed\n            // （2026-10-18 22:09 实测又崩一次）。\n            syntax = 'fetch-failed';\n            ready = false;\n            detail = 'bundle-unavailable';\n          } else {\n            const text = await bundleRes.text();\n            if (!text || text.length < 200) {\n              syntax = 'too-short';\n              ready = false;\n              detail = 'bundle-too-short';\n            } else {\n              try {\n                // 只编译不执行：能过说明语法是好的\n                new Function(text);\n                syntax = 'ok';\n              } catch (compileError) {\n                syntax = 'syntax-error';\n                ready = false;\n                detail = 'bundle-syntax-error';\n              }\n            }\n          }\n        }\n      }\n    } catch (error) {\n      syntax = 'check-failed';\n    }\n\n    return json(res, 200, { ok: true, ready, detail, syntax });\n  }\n\n  // webServer 可能在 apply 那一刻还没挂上，所以用 ctx.inject 等它就位再注册。\n  try {\n    if (typeof ctx.inject === 'function') {\n      ctx.inject(['webServer'], (host) => {\n        const webServer = host.webServer;\n        // clientModules 是可选服务：拿不到就让接口报 unknown，不阻断其它路由。\n        const getClientModules = () => {\n          try {\n            return typeof host.get === 'function' ? host.get('clientModules') : undefined;\n          } catch {\n            return undefined;\n          }\n        };\n\n        host.effect(() => webServer.register({\n          kind: 'exact',\n          path: ROUTE_STATUS,\n          handler: (req, res) => onStatus(req, res, webServer),\n        }, 'dsh-restart-dock: status route'));\n\n        host.effect(() => webServer.register({\n          kind: 'exact',\n          path: ROUTE_RESTART,\n          handler: (req, res) => onRestart(req, res, webServer),\n        }, 'dsh-restart-dock: restart route'));\n\n        host.effect(() => webServer.register({\n          kind: 'exact',\n          path: ROUTE_BUNDLE,\n          handler: (req, res) => onBundleReady(req, res, webServer, getClientModules),\n        }, 'dsh-restart-dock: bundle health route'));\n      });\n    }\n  } catch {\n    /* 没有 web server 的表面：小框不出现，其它一切不变 */\n  }\n}\n"
    },
    {
      "path": "client.js",
      "content": "/**\n * dsh-restart-dock · 客户端半 —— 界面上的那个小框。\n *\n * 两个动作：\n *   · **重启 DSH** —— 连点两次确认后，POST 给宿主半，由它起一个脱离宿主的 helper 去「停 + 拉」。\n *     点完会自己轮询 `/status`：先确认宿主真的停过（连不上），再等到它回来（又连上）→ 自动刷新。\n *   · **刷新页面** —— `location.reload()`，纯前端，任何平台都行。\n *\n * 位置：整块都能拖（按住走一段就变成拖动，松手贴边）。收起后那个小圆点也一样能拖。\n * 位置存在 localStorage，刷新/重启都在原处。座位是 `shell.overlay`（整框浮动层，不占布局）。\n *\n * 兜底：外面包一层错误边界 —— 这个组件自己出问题时**只让小框消失**，\n * 不让一个装饰性的浮层把整个界面拖下水。\n */\n\nwindow.__ModuleLoader__.load({\n  id: 'dsh-restart-dock',\n  factory(require) {\n    const React = require('react');\n    const h = React.createElement;\n    const { Component, useCallback, useEffect, useRef, useState } = React;\n\n    const NS = 'dsh-restart-dock';\n    const BASE = '/dsh-restart-dock';\n    const MARK = { 'x-dsh-restart-dock': '1' };\n    const STORE_COLLAPSED = 'dsh-restart-dock:collapsed';\n    const STORE_POS = 'dsh-restart-dock:pos';\n\n    const EDGE = 48;      // 离边多近算「贴边」\n    const EDGE_GAP = 6;   // 贴边后留的缝\n    const MIN_DRAG = 6;   // 超过这么多像素才算拖动，不是点击\n    const HOLD_MS = 320;  // 按住这么久才算「开始拖」——防鼠标一抖就把小框粘走\n\n    const ZH = {\n      restart: '重启',\n      reload: '刷新',\n      confirm: '确认重启？',\n      cancel: '取消',\n      sending: '正在排程…',\n      restarting: '正在重启，等它回来…',\n      waiting: '宿主已停，等新的起来…',\n      slow: '比预期久，可能没起来。可以点「刷新」，起不来就用救援脚本。',\n      done: '回来了，正在刷新…',\n      reloading: '正在刷新…',\n      pkgNotReady: '插件包还在重建，等几秒再刷新（这次没刷，怕刷成起不来的样子）',\n      lastOk: '上次重启：成功',\n      lastFail: '上次重启：失败',\n      collapse: '收起（收起后也能拖）',\n      expand: '重启 / 刷新',\n      dragHint: '按住可拖动',\n      restartHint: '重启=停掉 DSH 再拉起（会断开几秒）；刷新=只重载当前页面。',\n      forbidden: '被拒绝：不是同一个界面发来的请求。',\n      unsupported: '这个平台暂不支持一键重启，请用「刷新」。',\n      failed: '重启没成功',\n      ask: '什么时候重启？',\n      now: '立即',\n      after30: '30 秒',\n      after60: '60 秒',\n      after120: '2 分钟',\n      countdown: (n) => `${n} 秒后重启`,\n      abort: '取消重启',\n    };\n\n    const EN = {\n      restart: 'Restart',\n      reload: 'Reload',\n      confirm: 'Confirm?',\n      cancel: 'Cancel',\n      sending: 'Scheduling…',\n      restarting: 'Restarting, waiting for it…',\n      waiting: 'Host is down, waiting for the new one…',\n      slow: 'Taking longer than expected. Try Reload; if it never comes back use the rescue script.',\n      done: 'Back — reloading…',\n      reloading: 'Reloading…',\n      pkgNotReady: 'Plugin bundle is still rebuilding — wait a few seconds and try again (skipped, so the page stays usable)',\n      lastOk: 'Last restart: OK',\n      lastFail: 'Last restart: failed',\n      collapse: 'Collapse (still draggable)',\n      expand: 'Restart / Reload',\n      dragHint: 'Hold to drag',\n      restartHint: 'Restart stops and relaunches DSH (a few seconds offline). Reload only refreshes this page.',\n      forbidden: 'Refused: not the same page origin.',\n      unsupported: 'One-click restart is Windows-only here; use Reload.',\n      failed: 'Restart failed',\n      ask: 'When to restart?',\n      now: 'Now',\n      after30: '30s',\n      after60: '60s',\n      after120: '2 min',\n      countdown: (n) => `Restarting in ${n}s`,\n      abort: 'Cancel restart',\n    };\n\n    function pickLang() {\n      try {\n        const raw = String((navigator && navigator.language) || 'zh');\n        return raw.toLowerCase().indexOf('zh') === 0 ? ZH : EN;\n      } catch {\n        return ZH;\n      }\n    }\n\n    function clamp(value, min, max) {\n      return Math.min(Math.max(value, min), Math.max(min, max));\n    }\n\n    /**\n     * 位置按「贴哪条边 + 离边多远」记，而不是记绝对坐标。\n     * 这样窗口放大/缩小/全屏时，小框自动跟着边框走，不会跑到视口外面看不见。\n     */\n    function readPos() {\n      try {\n        const raw = localStorage.getItem(STORE_POS);\n        if (!raw) return null;\n        const parsed = JSON.parse(raw);\n\n        if (parsed\n          && (parsed.side === 'left' || parsed.side === 'right')\n          && (parsed.vSide === 'top' || parsed.vSide === 'bottom')\n          && Number.isFinite(parsed.dx) && Number.isFinite(parsed.dy)) {\n          return { side: parsed.side, dx: parsed.dx, vSide: parsed.vSide, dy: parsed.dy };\n        }\n\n        // 兼容旧格式（绝对 left/top）：换算成最近的边。\n        if (parsed && Number.isFinite(parsed.left) && Number.isFinite(parsed.top)) {\n          const W = (typeof window !== 'undefined' && window.innerWidth) || 1280;\n          const H = (typeof window !== 'undefined' && window.innerHeight) || 800;\n          const w = 150;\n          const ht = 44;\n          const distLeft = parsed.left;\n          const distRight = W - (parsed.left + w);\n          const distTop = parsed.top;\n          const distBottom = H - (parsed.top + ht);\n          return {\n            side: distRight <= distLeft ? 'right' : 'left',\n            dx: Math.max(4, Math.round(distRight <= distLeft ? distRight : distLeft)),\n            vSide: distBottom <= distTop ? 'bottom' : 'top',\n            dy: Math.max(4, Math.round(distBottom <= distTop ? distBottom : distTop)),\n          };\n        }\n      } catch { /* 读不到就用默认位置 */ }\n      return null;\n    }\n\n    function writePos(pos) {\n      try { localStorage.setItem(STORE_POS, JSON.stringify(pos)); } catch { /* 忽略 */ }\n    }\n\n    function defaultPos() {\n      // 默认贴右上角。\n      return { side: 'right', dx: 14, vSide: 'top', dy: 112 };\n    }\n\n    /** 把一块矩形换算成「最近的边 + 距离」。 */\n    function toAnchor(left, top, width, height) {\n      const W = (typeof window !== 'undefined' && window.innerWidth) || 1280;\n      const H = (typeof window !== 'undefined' && window.innerHeight) || 800;\n      const distLeft = Math.max(0, left);\n      const distRight = Math.max(0, W - (left + width));\n      const distTop = Math.max(0, top);\n      const distBottom = Math.max(0, H - (top + height));\n\n      // 离边 48px 内直接吸上去\n      let side = distRight <= distLeft ? 'right' : 'left';\n      let dx = Math.round(Math.min(distLeft, distRight));\n      if (Math.min(distLeft, distRight) < EDGE) dx = EDGE_GAP;\n\n      let vSide = distBottom <= distTop ? 'bottom' : 'top';\n      let dy = Math.round(Math.min(distTop, distBottom));\n      if (Math.min(distTop, distBottom) < EDGE) dy = EDGE_GAP;\n\n      return {\n        side,\n        dx: Math.max(EDGE_GAP, dx),\n        vSide,\n        dy: Math.max(EDGE_GAP, dy),\n      };\n    }\n\n    const CSS = `\n.rd-wrap { position: fixed; z-index: 60; display: flex; align-items: center;\n  font-size: 12px; line-height: 1; touch-action: none; user-select: none;\n  -webkit-user-select: none; cursor: grab; }\n.rd-wrap.rd-dragging { cursor: grabbing; }\n.rd-wrap.rd-dragging .rd-card, .rd-wrap.rd-dragging .rd-dot { opacity: 1; }\n.rd-card { display: flex; align-items: center; gap: 6px; padding: 6px;\n  border-radius: 11px; border: 1px solid rgba(128,128,128,.32);\n  background: rgba(128,128,128,.12); color: inherit;\n  box-shadow: 0 6px 22px rgba(0,0,0,.16); backdrop-filter: blur(8px);\n  opacity: .78; transition: opacity .15s ease; }\n.rd-card:hover { opacity: 1; }\n.rd-btn { font: inherit; font-size: 12px; line-height: 1; padding: 7px 10px; border-radius: 7px;\n  cursor: pointer; border: 1px solid rgba(128,128,128,.35);\n  background: rgba(128,128,128,.08); color: inherit; white-space: nowrap; }\n.rd-btn:hover { background: rgba(128,128,128,.2); }\n.rd-btn:disabled { opacity: .45; cursor: default; }\n.rd-btn.rd-warn { border-color: rgba(210,153,34,.6); color: #d29922; }\n.rd-btn.rd-warn:hover { background: rgba(210,153,34,.16); }\n.rd-btn.rd-danger { border-color: rgba(248,81,73,.65); background: rgba(248,81,73,.14); color: #f85149; }\n.rd-msg { font-size: 11px; opacity: .72; max-width: 180px; }\n.rd-count { font-variant-numeric: tabular-nums; opacity: .9; }\n.rd-dot { width: 30px; height: 30px; padding: 0; border-radius: 999px; display: flex;\n  align-items: center; justify-content: center; font-size: 13px; }\n.rd-dot-wrap { display: flex; align-items: center; }\n.rd-tip { position: absolute; right: 0; top: calc(100% + 6px); white-space: nowrap;\n  font-size: 11px; padding: 5px 8px; border-radius: 7px; pointer-events: none;\n  background: rgba(30,30,32,.94); color: #eee; opacity: 0; transition: opacity .12s; }\n.rd-wrap:hover .rd-tip { opacity: 1; }\n.rd-fx { position: fixed; inset: 0; width: 100vw; height: 100vh;\n  pointer-events: none; z-index: 9999; }\n`;\n\n    function Dock() {\n      const T = useRef(pickLang()).current;\n      const wrapRef = useRef(null);\n      const [collapsed, setCollapsed] = useState(() => {\n        try { return localStorage.getItem(STORE_COLLAPSED) === '1'; } catch { return false; }\n      });\n      const [pos, setPos] = useState(() => readPos() || defaultPos());\n      const [dragging, setDragging] = useState(false);\n      const [phase, setPhase] = useState('idle'); // idle | sending | restarting | slow\n      const [asking, setAsking] = useState(false);   // 正在问「什么时候重启」\n      const [countdown, setCountdown] = useState(null); // 倒计时秒数，null = 没在倒数\n      const [note, setNote] = useState('');\n      const [last, setLast] = useState(null);\n\n      const armTimer = useRef(null);      // 保留：旧逻辑清理用\n      const countdownTimer = useRef(null);\n      const restartRef = useRef(null);    // 最新的 doRestart，给倒计时回调调用\n      const pollTimer = useRef(null);\n      const sawDown = useRef(false);\n      const startedAt = useRef(0);\n      const alive = useRef(true);\n      const drag = useRef(null);       // 进行中的拖动\n      const finishDragRef = useRef(null); // 供长按后的 window 监听调用\n      const lastDragAt = useRef(0);    // 最近一次拖动结束的时刻（用来吞掉误触的 click）\n\n      useEffect(() => {\n        alive.current = true;\n        return () => {\n          alive.current = false;\n          if (armTimer.current) clearTimeout(armTimer.current);\n          if (countdownTimer.current) clearInterval(countdownTimer.current);\n          if (pollTimer.current) clearTimeout(pollTimer.current);\n        };\n      }, []);\n\n      // 拖动过程中用绝对 left/top（手感直接），松手后换算成「贴边 + 距离」。\n      // resize 时不需要重算：锚点是相对边的，窗口怎么变它都跟着走。\n      const [dragBox, setDragBox] = useState(null);\n\n      /* ---------------- 粒子特效（给用户看的反馈） ---------------- */\n\n      // 点「刷新」时页面会瞬间被替换掉，什么都没发生的样子。\n      // 所以先播一段从左上角洒向右下角的粒子，约 0.9 秒，播完再真正刷新。\n      const [fxOn, setFxOn] = useState(false);\n      const fxEndRef = useRef(null);\n      const fxCanvasRef = useRef(null);\n\n      const playFx = useCallback((after) => {\n        fxEndRef.current = typeof after === 'function' ? after : null;\n        setFxOn(true);\n      }, []);\n\n      // 调试入口：**不刷新页面**也能放一次特效。\n      // 加它是因为「点刷新看特效」会把 bundle 缓存撞坏（文件变了 rev 没变 →\n      // import failed → 整个 web boot 起不来）。以后验特效只调这个钩子。\n      useEffect(() => {\n        const trigger = () => playFx();\n        window.__dshRestartDockFx = trigger;\n        return () => {\n          if (window.__dshRestartDockFx === trigger) delete window.__dshRestartDockFx;\n        };\n      }, [playFx]);\n\n      useEffect(() => {\n        if (!fxOn) return undefined;\n        const canvas = fxCanvasRef.current;\n        if (!canvas) { setFxOn(false); return undefined; }\n        const dpr = Math.min(window.devicePixelRatio || 1, 2);\n        const W = window.innerWidth;\n        const H = window.innerHeight;\n        canvas.width = Math.round(W * dpr);\n        canvas.height = Math.round(H * dpr);\n        const ctx = canvas.getContext('2d');\n        if (!ctx) { setFxOn(false); return undefined; }\n        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n\n        const DURATION = 2000;   // 2 秒一道浪\n\n        // 经典「粒子海」做法：整屏铺一层点阵，每个点的亮度由**同一个正弦波**\n        // 在它那个位置的相位决定 —— 波峰处的点亮起、变大，波谷处的点暗下去。\n        // 波沿屏幕对角线（左上 → 右下）推进，看到的就是几道斜向亮带在扫。\n        // 这样整片屏幕都在响应同一道波，而不是我随手摆一堆点。\n        const diag = Math.hypot(W, H);\n        const dirX = W / diag;\n        const dirY = H / diag;\n        const TAU = Math.PI * 2;\n\n        const STEP = 22;      // 点阵间距（px）：间距越大越稀\n        const KEEP = 0.22;    // 再随机丢掉大部分点，留出「稀树星空」的感觉\n        const parts = [];\n        for (let y = -STEP; y < H + STEP; y += STEP) {\n          for (let x = -STEP; x < W + STEP; x += STEP) {\n            if (Math.random() > KEEP) continue;\n            parts.push({\n              x: x + (Math.random() - 0.5) * STEP * 0.9,\n              y: y + (Math.random() - 0.5) * STEP * 0.9,\n              // 沿对角线方向的投影 = 波相位的空间部分\n              s: (x * dirX + y * dirY) / diag,\n              jitter: 0.55 + Math.random() * 0.45,\n              hue: 194 + Math.random() * 42,\n            });\n          }\n        }\n\n        let raf = 0;\n        let finished = false;\n        const begin = performance.now();\n\n        const frame = (now) => {\n          if (finished) return;\n          const t = Math.min(1, (now - begin) / DURATION);\n\n          if (t >= 1) {\n            finished = true;\n            ctx.clearRect(0, 0, W, H);\n            const cb = fxEndRef.current;\n            fxEndRef.current = null;\n            setFxOn(false);\n            if (typeof cb === 'function') cb();\n            return;\n          }\n\n          ctx.clearRect(0, 0, W, H);\n          ctx.globalCompositeOperation = 'lighter';\n\n          const travel = t * 3;\n\n          for (const q of parts) {\n            const phase = q.s * TAU * 2.2 - travel * TAU * 0.55;\n\n            // 三层正弦叠加：主浪 + 两道碎浪。单层是「规则的条纹」，\n            // 叠起来才有真实海面那种长短不齐的碎浪感。\n            const wave =\n              Math.sin(phase) * 0.62 +\n              Math.sin(phase * 1.93 + 1.7) * 0.26 +\n              Math.sin(phase * 0.47 + 3.1) * 0.12;\n\n            if (wave <= 0) continue;                       // 只画波峰那半边\n\n            const lum = Math.pow(wave, 1.9) * q.jitter;\n            if (lum <= 0.02) continue;\n\n            const depth = 0.75 + q.s * 0.55;               // 右下角稍大，给点纵深\n            const size = (1.1 + lum * 6.4) * depth;\n\n            // 波峰越亮越偏白，波坡偏蓝。\n            const light = 58 + lum * 38;\n\n            // 蓝色十字星星：一横一竖 + 中心亮点，越亮臂越长。\n            const arm = size * (1.7 + lum * 1.7);\n            const thick = Math.max(1.0, size * 0.46);\n\n            // 交叉处的柔光\n            if (lum > 0.35) {\n              ctx.globalAlpha = Math.min(0.34, lum * 0.3);\n              ctx.fillStyle = `hsl(${q.hue} 100% 78%)`;\n              ctx.beginPath();\n              ctx.arc(q.x, q.y, arm * 0.85, 0, TAU);\n              ctx.fill();\n            }\n\n            ctx.globalAlpha = Math.min(1, lum * 1.75);\n            ctx.fillStyle = `hsl(${q.hue} 96% ${light}%)`;\n            // 横臂\n            ctx.fillRect(q.x - arm, q.y - thick / 2, arm * 2, thick);\n            // 竖臂\n            ctx.fillRect(q.x - thick / 2, q.y - arm, thick, arm * 2);\n            // 中心亮核\n            ctx.beginPath();\n            ctx.arc(q.x, q.y, thick * 1.15, 0, TAU);\n            ctx.fill();\n          }\n\n          ctx.globalAlpha = 1;\n          ctx.globalCompositeOperation = 'source-over';\n          raf = requestAnimationFrame(frame);\n        };\n        raf = requestAnimationFrame(frame);\n\n        return () => {\n          finished = true;\n          cancelAnimationFrame(raf);\n        };\n      }, [fxOn]);\n\n      /* ---------------- 拖动 ---------------- */\n\n      const onPointerDown = useCallback((event) => {\n        if (event.button !== 0) return;\n        const el = wrapRef.current;\n        if (!el) return;\n        const rect = el.getBoundingClientRect();\n        const d = {\n          id: event.pointerId,\n          sx: event.clientX,\n          sy: event.clientY,\n          bl: rect.left,\n          bt: rect.top,\n          w: rect.width,\n          h: rect.height,\n          box: null,\n          moved: false,\n          holdReady: false,\n          holdTimer: null,\n        };\n        // **必须长按才进入拖动**。原来只要鼠标移动超过 6px 就开始拖，\n        // 结果「没打算拖、只是手一抖」小框就粘在鼠标上跟着跑（用户实测反馈）。\n        // 这里按住 320ms 后才允许拖；期间松开或不移动都当普通点击。\n        d.holdTimer = setTimeout(() => {\n          if (drag.current !== d) return;\n          d.holdReady = true;\n          setDragging(true);   // cursor 变 grabbing，给个「现在可以拖了」的信号\n          // 用 window 监听代替 setPointerCapture：capture 在 Electron 里事件送达发黏，\n          // 拖动明显不跟手（2026-10-20 对比：另一插件用 window mousemove 就跟得紧）。\n          const winMove = (ev) => {\n            if (drag.current !== d || !d.holdReady) return;\n            d.moved = true;\n            const box = {\n              left: clamp(d.bl + (ev.clientX - d.sx), 4, ((window.innerWidth || 1280) - d.w - 4)),\n              top: clamp(d.bt + (ev.clientY - d.sy), 4, ((window.innerHeight || 800) - d.h - 4)),\n            };\n            d.box = box;\n            // 拖动期间直接写样式：不走 React state，避免每帧重渲染整块面板。\n            const el2 = wrapRef.current;\n            if (el2) {\n              el2.style.left = box.left + 'px';\n              el2.style.top = box.top + 'px';\n            }\n            ev.preventDefault();\n          };\n          const winUp = (ev) => {\n            window.removeEventListener('pointermove', winMove);\n            window.removeEventListener('pointerup', winUp);\n            window.removeEventListener('pointercancel', winUp);\n            if (finishDragRef.current) finishDragRef.current(ev);\n          };\n          window.addEventListener('pointermove', winMove);\n          window.addEventListener('pointerup', winUp);\n          window.addEventListener('pointercancel', winUp);\n        }, HOLD_MS);\n        drag.current = d;\n        // **不要在这里 setPointerCapture**。实测（2026-10-18）它会把后续 pointer 事件\n        // 全部捕获到这个元素上，导致「真实鼠标点击」的 click 根本不触发 ——\n        // 表现就是小框渲染正常、elementFromPoint 也命中按钮，但怎么点都没反应，\n        // 而编程 element.click() 却是好的。capture 推迟到确认开始拖动时再做。\n      }, []);\n\n      const onPointerMove = useCallback((event) => {\n        const d = drag.current;\n        if (!d || d.id !== event.pointerId) return;\n        // 没长按够时间 → 这不是拖动，忽略移动\n        if (!d.holdReady) return;\n        const dx = event.clientX - d.sx;\n        const dy = event.clientY - d.sy;\n        if (!d.moved) d.moved = true;\n        const el = wrapRef.current;\n        const w = el ? el.offsetWidth : 150;\n        const ht = el ? el.offsetHeight : 44;\n        setDragBox({\n          left: clamp(d.bl + dx, 4, ((window.innerWidth || 1280) - w - 4)),\n          top: clamp(d.bt + dy, 4, ((window.innerHeight || 800) - ht - 4)),\n        });\n        event.preventDefault();\n      }, []);\n\n      const finishDrag = useCallback((event) => {\n        const d = drag.current;\n        if (!d) return;\n        if (d.holdTimer) clearTimeout(d.holdTimer);\n        drag.current = null;\n        try { wrapRef.current?.releasePointerCapture(d.id); } catch { /* 忽略 */ }\n        if (!d.moved) {\n          // 短按、或者长按了但没移动 —— 都按点击处理，把状态复原\n          setDragBox(null);\n          setDragging(false);\n          return;\n        }\n        lastDragAt.current = Date.now();\n        // 松手：把拖到的地方换算成「贴哪条边 + 离边多远」。\n        const box = d.box;\n        if (box) {\n          const next = toAnchor(box.left, box.top, d.w || 150, d.h || 44);\n          writePos(next);\n          setPos(next);\n        }\n        setDragBox(null);\n        setDragging(false);\n        if (event && typeof event.preventDefault === 'function') event.preventDefault();\n      }, []);\n\n      finishDragRef.current = finishDrag;\n\n      /** 拖动刚结束的那一下点击要吞掉，否则一拖就会顺手触发按钮。 */\n      const swallowAfterDrag = useCallback(() => Date.now() - lastDragAt.current < 180, []);\n\n      const onButtonClick = useCallback((fn) => (event) => {\n        if (swallowAfterDrag()) {\n          try { event.preventDefault(); event.stopPropagation(); } catch { /* 忽略 */ }\n          return;\n        }\n        fn();\n      }, [swallowAfterDrag]);\n\n      const rememberCollapsed = useCallback((next) => {\n        setCollapsed(next);\n        try { localStorage.setItem(STORE_COLLAPSED, next ? '1' : '0'); } catch { /* 忽略 */ }\n      }, []);\n\n      /* ---------------- 宿主交互 ---------------- */\n\n      // 首次读一眼上次重启的报告（不影响主流程）。\n      useEffect(() => {\n        let stop = false;\n        (async () => {\n          try {\n            const res = await fetch(BASE + '/status', { headers: MARK, cache: 'no-store' });\n            if (!res.ok) return;\n            const data = await res.json();\n            if (!stop && data && data.restart) setLast(data.restart.last || null);\n          } catch { /* 宿主刚起/还没路由，忽略 */ }\n        })();\n        return () => { stop = true; };\n      }, []);\n\n      const pollUntilBack = useCallback(() => {\n        const tick = async () => {\n          if (!alive.current) return;\n          try {\n            const res = await fetch(BASE + '/status', { headers: MARK, cache: 'no-store' });\n            if (res.ok) {\n              if (sawDown.current) {\n                // 宿主真的停过又回来了：自动刷新，用户不用自己按。\n                setPhase('restarting');\n                setNote(T.done);\n                try { window.location.reload(); } catch { /* 忽略 */ }\n                return;\n              }\n            } else {\n              sawDown.current = true;\n            }\n          } catch {\n            sawDown.current = true;\n          }\n          if (sawDown.current) setNote(T.waiting);\n          // 整个重启最长可能走 70 秒左右（等停 + 补刀 + 拉起轮询），\n          // 所以放弃阈值给到 90 秒 —— 别在它还好好地重启时先说\"比预期久\"。\n          if (Date.now() - startedAt.current > 90000) {\n            setPhase('slow');\n            setNote(T.slow);\n            return;\n          }\n          pollTimer.current = setTimeout(tick, 900);\n        };\n        tick();\n      }, [T]);\n\n      const doRestart = useCallback(async () => {\n        if (phase === 'sending' || phase === 'restarting') return;\n        setPhase('sending');\n        setNote(T.sending);\n        try {\n          const res = await fetch(BASE + '/restart', {\n            method: 'POST',\n            headers: MARK,\n            cache: 'no-store',\n          });\n          const data = await res.json().catch(() => ({}));\n          if (!res.ok || !data.ok) {\n            setPhase('idle');\n            if (res.status === 403) setNote(T.forbidden);\n            else if (res.status === 501) setNote(T.unsupported);\n            else if (res.status === 409) setNote(data.detail || T.restarting);\n            else setNote(T.failed + (data.detail ? '：' + data.detail : ''));\n            return;\n          }\n          startedAt.current = Date.now();\n          setPhase('restarting');\n          setNote(T.restarting);\n          playFx();          // 让「正在重启」有个看得见的起手\n          pollUntilBack();\n        } catch {\n          setPhase('idle');\n          setNote(T.failed);\n        }\n      }, [phase, T, pollUntilBack, playFx]);\n\n      // 倒计时的回调里要调用「最新那一版」doRestart，不能用闭包里过期的。\n      restartRef.current = doRestart;\n\n      /**\n       * 点「重启」不再直接干，先问一句「什么时候」：\n       * 立即 / 30 秒 / 60 秒 / 2 分钟 / 取消。\n       * 选延迟就在界面上倒计时，随时能撤回 —— 给自己留个反悔的窗口。\n       */\n      const openAsk = useCallback(() => {\n        if (phase === 'sending' || phase === 'restarting') return;\n        setAsking((cur) => !cur);\n        setNote(T.ask);\n      }, [phase, T]);\n\n      // 问询框开出来之后，几秒不操作就自己收回去 —— 别让它一直占着屏幕。\n      // 选任一选项（立即/30s/…）或点「取消」都会把 asking 置 false，cleanup 顺手清掉定时器。\n      useEffect(() => {\n        if (!asking) return undefined;\n        const t = setTimeout(() => {\n          setAsking(false);\n          setNote('');\n        }, 5000);\n        return () => clearTimeout(t);\n      }, [asking]);\n\n      const startCountdown = useCallback((seconds) => {\n        setAsking(false);\n        if (countdownTimer.current) clearInterval(countdownTimer.current);\n        setCountdown(seconds);\n        countdownTimer.current = setInterval(() => {\n          setCountdown((cur) => {\n            if (cur === null) return null;\n            if (cur <= 1) {\n              if (countdownTimer.current) {\n                clearInterval(countdownTimer.current);\n                countdownTimer.current = null;\n              }\n              // 用 ref 拿最新的 doRestart，避开闭包过期\n              const fire = restartRef.current;\n              setNote('');\n              if (fire) fire();\n              return null;\n            }\n            return cur - 1;\n          });\n        }, 1000);\n      }, []);\n\n      const abortCountdown = useCallback(() => {\n        if (countdownTimer.current) {\n          clearInterval(countdownTimer.current);\n          countdownTimer.current = null;\n        }\n        setCountdown(null);\n        setAsking(false);\n        setNote('');\n      }, []);\n\n      const doReload = useCallback(async () => {\n        if (phase === 'sending' || phase === 'restarting' || phase === 'reloading') return;\n        // 用独立的 'reloading' 状态：之前复用了 'sending'，导致刷新时按钮写着\n        // 「正在排程…」（那是重启的文案），看起来像点错了东西。\n        setPhase('reloading');\n        setNote(T.reloading);\n\n        // 刷新前先问宿主：插件包现在稳不稳。\n        // 为什么：client 插件包是按需拼的，本地文件刚改过会有一小段「重建中」；\n        // 这个窗口里刷新会拿到坏包 → import failed → 整个 web boot 起不来\n        // （2026-10-18 21:37 就是这么刷崩的，只能手动重启）。\n        // 宿主侧用 clientModules 的文件基线对比磁盘，能准确判断这个窗口。\n        let ready = true;\n        try {\n          const res = await fetch(BASE + '/bundle-ready', { headers: MARK, cache: 'no-store' });\n          if (res.ok) {\n            const data = await res.json().catch(() => null);\n            if (data && data.ready === false) ready = false;\n          }\n        } catch {\n          ready = true; // 查不到就放行，不拿接口故障阻断用户\n        }\n\n        if (!ready) {\n          setPhase('idle');\n          setNote(T.pkgNotReady);\n          return;\n        }\n\n        // 页面一刷新就什么都没了，所以先把粒子播完（约 2 秒）再 reload。\n        playFx(() => {\n          try {\n            // **不要把 location.reload() 当成安全操作**。\n            // 对照实验（2026-10-18）：页面稳定的情况下，强制刷新 / 普通刷新 /\n            // 页面内 reload 都不会崩；但「刚改完 client.js 不久」再刷新，\n            // 会拿到页面自己记的旧版本包 → import failed → 整个 web boot 起不来。\n            // 所以这里带一个时间戳参数强制走新 URL，绕开页面级缓存。\n            const u = new URL(window.location.href);\n            u.searchParams.set('_dsh_r', String(Date.now()));\n            window.location.replace(u.toString());\n          } catch {\n            try { window.location.reload(); } catch { setPhase('idle'); }\n          }\n        });\n      }, [phase, T, playFx]);\n\n      /* ---------------- 渲染 ---------------- */\n\n      const busy = phase === 'sending' || phase === 'restarting' || phase === 'reloading';\n      // 只有明确「拉起来了」才算成功；failed 才算失败；armed/dry-run 之类不表态。\n      const lastText = last\n        ? (last.state === 'relaunched' ? T.lastOk : (last.state === 'failed' ? T.lastFail : ''))\n        : '';\n\n      // 拖动中用绝对坐标；平时用「贴边 + 距离」，窗口缩放/全屏都自动跟着边框走。\n      const wrapStyle = dragBox\n        ? { left: dragBox.left + 'px', top: dragBox.top + 'px' }\n        : {\n          ...(pos.side === 'right' ? { right: pos.dx + 'px' } : { left: pos.dx + 'px' }),\n          ...(pos.vSide === 'bottom' ? { bottom: pos.dy + 'px' } : { top: pos.dy + 'px' }),\n        };\n\n      const wrapProps = {\n        ref: wrapRef,\n        className: 'rd-wrap' + (dragging ? ' rd-dragging' : ''),\n        style: wrapStyle,\n        onPointerDown,\n        onPointerMove,\n        onPointerUp: finishDrag,\n        onPointerCancel: finishDrag,\n      };\n\n      // 粒子画布是整屏 fixed 的，挂在哪个分支里都一样；只在播放时存在。\n      const fxCanvas = fxOn ? h('canvas', { className: 'rd-fx', ref: fxCanvasRef }) : null;\n\n      if (collapsed) {\n        return h('div', wrapProps,\n          h('style', null, CSS),\n          fxCanvas,\n          h('button', {\n            type: 'button',\n            className: 'rd-btn rd-dot',\n            title: lastText || T.expand,\n            'aria-label': T.expand,\n            onClick: onButtonClick(() => rememberCollapsed(false)),\n          }, '⏻'),\n          h('div', { className: 'rd-tip' }, lastText || T.dragHint),\n        );\n      }\n\n      return h('div', wrapProps,\n        h('style', null, CSS),\n        fxCanvas,\n        h('div', { className: 'rd-card' },\n          note ? h('span', { className: 'rd-msg' }, note) : null,\n\n          // 倒计时中：显示还剩几秒，旁边一个撤回。\n          countdown !== null\n            ? [\n              h('span', { key: 'cd', className: 'rd-msg rd-count' }, T.countdown(countdown)),\n              h('button', {\n                key: 'abort',\n                type: 'button',\n                className: 'rd-btn rd-danger',\n                onClick: onButtonClick(abortCountdown),\n              }, T.abort),\n            ]\n            // 问询中：立即 / 30 秒 / 60 秒 / 2 分钟。\n            : asking\n              ? [\n                h('button', {\n                  key: 'now',\n                  type: 'button',\n                  className: 'rd-btn rd-danger',\n                  disabled: busy,\n                  onClick: onButtonClick(() => { setAsking(false); setNote(''); doRestart(); }),\n                }, T.now),\n                h('button', {\n                  key: 'a30',\n                  type: 'button',\n                  className: 'rd-btn',\n                  disabled: busy,\n                  onClick: onButtonClick(() => startCountdown(30)),\n                }, T.after30),\n                h('button', {\n                  key: 'a60',\n                  type: 'button',\n                  className: 'rd-btn',\n                  disabled: busy,\n                  onClick: onButtonClick(() => startCountdown(60)),\n                }, T.after60),\n                h('button', {\n                  key: 'a120',\n                  type: 'button',\n                  className: 'rd-btn',\n                  disabled: busy,\n                  onClick: onButtonClick(() => startCountdown(120)),\n                }, T.after120),\n                h('button', {\n                  key: 'cancel',\n                  type: 'button',\n                  className: 'rd-btn',\n                  onClick: onButtonClick(() => { setAsking(false); setNote(''); }),\n                }, T.cancel),\n              ]\n              // 平时：重启 / 刷新 / 收起。\n              : [\n                h('button', {\n                  key: 'restart',\n                  type: 'button',\n                  className: 'rd-btn rd-warn',\n       